import { formatVisitReference } from '@truck-log/shared/contracts';
import { TruckVisit } from '@truck-log/server/data-access';

/**
 * Render the driver-facing visit slip without coupling presentation markup to
 * the visit orchestration service. Keeping this renderer pure makes the slip
 * independently testable while preserving the existing printed output.
 */
export function renderTruckVisitSlipHtml(
    visit: TruckVisit,
    settings: ReadonlyMap<string, string>,
): string {
    const plantLocationName = settings.get('plant_location_name')?.trim() || 'Fort Wayne';
    const configuredSiteName = settings.get('site_name')?.trim();
    const danaPlantName = /^dana\b/i.test(plantLocationName)
        ? plantLocationName
        : `Dana ${plantLocationName}`;
    // A legacy/default site_name of "Truck Log" is not useful on the driver's paper.
    // Prefer the database-backed plant identity while still allowing a real explicit
    // site_name override for facilities that need a different printed title.
    const siteName = configuredSiteName && configuredSiteName.toLowerCase() !== 'truck log'
        ? configuredSiteName
        : danaPlantName;
    const slipFooter = settings.get('slip_footer') ||
        'Return to the guard shack for final checkout before leaving the site.';
    // Keep the long internal visit_number for storage/search compatibility, but
    // never expose it as the driver-facing paper reference. The numeric primary
    // key is permanent and unique, so this gives guards/drivers a short reference
    // they can read aloud: TL-000123.
    const visitReference = formatVisitReference(visit.id);
    const danaLogoDataUri = 'data:image/png;base64,';
    const esc = (value: unknown) => String(value ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
    const timeZone = process.env.TZ || 'America/Indiana/Indianapolis';
    const dateTime = new Intl.DateTimeFormat('en-US', {
        timeZone,
        month: '2-digit',
        day: '2-digit',
        year: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
    });
    const fmtDateTime = (value: unknown, empty = '-') => {
        if (!value)
            return empty;
        const parsed = value instanceof Date ? value : new Date(String(value));
        return Number.isNaN(parsed.getTime()) ? String(value) : dateTime.format(parsed);
    };
    const field = (label: string, value: unknown, extraClass = '') => `
  <div class="field ${extraClass}">
    <div class="field-label">${esc(label)}</div>
    <div class="field-value">${esc(value || '-')}</div>
  </div>`;
    const notesHtml = visit.notes
        ? `<section class="section notes-section">
      <div class="section-title">Guard / Dock Notes</div>
      <div class="notes">${esc(visit.notes)}</div>
    </section>`
        : '';
    return `<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <title>${esc(visitReference)} - Driver Slip</title>
  <style>
@page { size: Letter portrait; margin: 0.22in 0.32in; }

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: #eef1f4;
  color: #111827;
  font-family: Arial, Helvetica, sans-serif;
}

body { padding: 18px; }

.screen-toolbar {
  width: 100%;
  max-width: 7.8in;
  margin: 0 auto 10px;
  display: flex;
  justify-content: flex-end;
}

.print-button {
  border: 0;
  border-radius: 7px;
  padding: 9px 16px;
  background: #173a5c;
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
}

.slip {
  width: 100%;
  max-width: 7.8in;
  min-height: 10.3in;
  margin: 0 auto;
  padding: 0.22in 0.25in 0.18in;
  background: #fff;
  border: 1px solid #c8cdd3;
  box-shadow: 0 2px 12px rgba(0,0,0,.10);
  display: flex;
  flex-direction: column;
}

.header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: end;
  padding-bottom: 10px;
  border-bottom: 3px solid #111827;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.dana-logo {
  width: 82px;
  height: auto;
  flex: 0 0 auto;
  display: block;
}

.brand-copy {
  min-width: 0;
}

.site-name {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
  font-weight: 800;
  letter-spacing: .01em;
}

.document-title {
  margin-top: 4px;
  font-size: 11px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: #4b5563;
}

.visit-reference {
  min-width: 175px;
  text-align: right;
}

.visit-reference .label {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: #6b7280;
}

.visit-reference .value {
  margin-top: 3px;
  font-family: "Courier New", monospace;
  font-size: 17px;
  font-weight: 800;
  letter-spacing: .03em;
}

.hero {
  display: grid;
  grid-template-columns: 1fr 1.25fr;
  gap: 10px;
  margin: 12px 0;
}

.hero-box {
  min-height: 104px;
  border: 2px solid #111827;
  border-radius: 5px;
  padding: 10px 12px;
}

.hero-label {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: #4b5563;
}

.dock-value {
  margin-top: 6px;
  font-size: 44px;
  line-height: 1;
  font-weight: 900;
  letter-spacing: .02em;
}

.load-value {
  margin-top: 8px;
  font-size: 25px;
  line-height: 1.05;
  font-weight: 900;
  overflow-wrap: anywhere;
}

.hero-sub {
  margin-top: 9px;
  font-size: 11px;
  font-weight: 700;
  color: #374151;
}

.section {
  margin-top: 10px;
  border: 1px solid #9ca3af;
  border-radius: 5px;
  overflow: hidden;
  break-inside: avoid;
  page-break-inside: avoid;
}

.section-title {
  padding: 6px 9px;
  border-bottom: 1px solid #9ca3af;
  background: #eef1f4;
  font-size: 10px;
  line-height: 1.2;
  font-weight: 900;
  letter-spacing: .11em;
  text-transform: uppercase;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.field {
  min-height: 48px;
  padding: 7px 9px;
  border-right: 1px solid #d1d5db;
  border-bottom: 1px solid #d1d5db;
}

.field:nth-child(2n) { border-right: 0; }
.field:nth-last-child(-n+2) { border-bottom: 0; }

.field-label {
  font-size: 8px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: .10em;
  text-transform: uppercase;
  color: #6b7280;
}

.field-value {
  margin-top: 3px;
  font-size: 14px;
  line-height: 1.25;
  font-weight: 750;
  overflow-wrap: anywhere;
}

.route-grid .field-value { font-size: 13px; }

.instructions {
  margin: 0;
  padding: 8px 12px 8px 28px;
}

.instructions li {
  margin: 0 0 4px;
  padding-left: 2px;
  font-size: 11px;
  line-height: 1.35;
  font-weight: 650;
}

.instructions li:last-child { margin-bottom: 0; }

.notes {
  min-height: 58px;
  padding: 8px 10px;
  font-size: 11px;
  line-height: 1.4;
  white-space: pre-wrap;
}

.checkout {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 16px;
  padding: 11px 10px 9px;
}

.write-line {
  padding-top: 16px;
  border-bottom: 1px solid #111827;
  font-size: 9px;
  font-weight: 800;
  color: #4b5563;
}

.signoff-spacer {
  flex: 1 1 24px;
  min-height: 10px;
}

.signoff-section {
  margin-top: 0;
}

.final-notice {
  margin-top: 8px;
  padding: 9px 11px;
  border: 2px solid #111827;
  text-align: center;
  font-size: 12px;
  line-height: 1.35;
  font-weight: 900;
  text-transform: uppercase;
}

.configured-footer {
  margin-top: 5px;
  text-align: center;
  font-size: 10px;
  line-height: 1.35;
  font-weight: 700;
  color: #374151;
}

.print-meta {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  margin-top: 7px;
  padding-top: 6px;
  border-top: 1px solid #d1d5db;
  font-size: 8px;
  line-height: 1.25;
  color: #6b7280;
}

@media print {
  html, body {
    background: #fff;
    width: 100%;
  }

  body { padding: 0; }

  .screen-toolbar { display: none !important; }

  .slip {
    width: 100%;
    max-width: none;
    min-height: 10.56in;
    border: 0;
    box-shadow: none;
    padding: 0.02in 0.04in 0.03in;
  }

  /* Keep the printed slip safely inside the physical page while using
     nearly the full Letter height. The flexible spacer absorbs the
     remaining height rather than allowing the footer/meta to spill. */
  .header { padding-bottom: 8px; }
  .hero { margin: 10px 0; }
  .hero-box { min-height: 100px; padding: 9px 12px; }
  .section { margin-top: 8px; }
  .field { min-height: 46px; padding: 6px 9px; }
  .instructions { padding-top: 7px; padding-bottom: 7px; }
  .instructions li { margin-bottom: 3px; }
  .notes { min-height: 54px; padding: 7px 10px; }
  .checkout { padding: 9px 10px 8px; }
  .write-line { padding-top: 14px; }
  .signoff-spacer { flex: 1 1 auto; min-height: 14px; }
  .final-notice { margin-top: 7px; padding: 7px 11px; }
  .configured-footer { margin-top: 4px; }
  .print-meta { margin-top: 5px; padding: 5px 2px 0; }
  .print-meta span:last-child { white-space: nowrap; }

  .section-title {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
}
  </style>
</head>
<body>
  <div class="screen-toolbar">
<button class="print-button" onclick="window.print()">Print Driver Slip</button>
  </div>

  <main class="slip">
<header class="header">
  <div class="brand">
    <img class="dana-logo" src="${danaLogoDataUri}" alt="Dana">
    <div class="brand-copy">
      <h1 class="site-name">${esc(siteName)}</h1>
      <div class="document-title">Driver / Dock Assignment Slip</div>
    </div>
  </div>
  <div class="visit-reference">
    <div class="label">Visit ID</div>
    <div class="value">${esc(visitReference)}</div>
  </div>
</header>

<section class="hero">
  <div class="hero-box">
    <div class="hero-label">Assigned Dock</div>
    <div class="dock-value">${esc(visit.dockCode || 'N/A')}</div>
    <div class="hero-sub">${esc(String(visit.direction || '').toUpperCase() || '-')}</div>
  </div>

  <div class="hero-box">
    <div class="hero-label">Load Number</div>
    <div class="load-value">${esc(visit.loadNumber || '-')}</div>
    <div class="hero-sub">Check-In: ${esc(fmtDateTime(visit.guardCheckInAt))}</div>
  </div>
</section>

<section class="section">
  <div class="section-title">Driver and Equipment</div>
  <div class="info-grid">
    ${field('Driver', visit.driverName)}
    ${field('Driver Phone', visit.driverPhone)}
    ${field('Carrier', visit.carrierName)}
    ${field('Tractor ID', visit.tractorId)}
    ${field('Trailer ID', visit.trailerId)}
    ${field('Drop Trailer', visit.isDropTrailer ? 'Yes' : 'No')}
    ${field('Scheduled Time', fmtDateTime(visit.scheduledAt, 'Not Scheduled'))}
    ${field('Direction', String(visit.direction || '').toUpperCase())}
  </div>
</section>

<section class="section">
  <div class="section-title">Routing</div>
  <div class="info-grid route-grid">
    ${field('Origin', visit.originName)}
    ${field('Destination', visit.destinationName)}
    ${""}
    ${field('Dock Assigned', fmtDateTime(visit.dockAssignedAt))}
  </div>
</section>

<section class="section">
  <div class="section-title">Driver Instructions</div>
  <ol class="instructions">
    <li>Proceed to the assigned dock shown at the top of this slip.</li>
    <li>Keep this slip with you while the truck is on site.</li>
    <li>Follow all posted plant traffic, safety, and dock instructions.</li>
    <li>After loading or unloading is complete, return to the guard shack for final checkout.</li>
  </ol>
</section>

${notesHtml}

<div class="signoff-spacer" aria-hidden="true"></div>

<section class="section signoff-section">
  <div class="section-title">Final Guard Checkout - Signoff</div>
  <div class="checkout">
    <div class="write-line">DRIVER SIGNATURE</div>
    <div class="write-line">TIME OUT</div>
    <div class="write-line">GUARD INITIALS</div>
  </div>
</section>

<div class="final-notice">Do not leave the site without final guard checkout.</div>
<div class="configured-footer">${esc(slipFooter)}</div>

<div class="print-meta">
  <span>${esc(siteName)} - Truck Log</span>
  <span>Visit ID ${esc(visitReference)}</span>
</div>
  </main>

  <script>
setTimeout(function () { window.print(); }, 350);
  </script>
</body>
</html>`;
}
